<?php
require_once dirname(__DIR__) . '/config/bootstrap.php';
require_once dirname(__DIR__) . '/models/OrderModel.php';
if (function_exists('require_admin')) { require_admin('login.php'); }
elseif (empty($_SESSION['admin_id']) || ($_SESSION['admin_role'] ?? '') !== 'admin') { header('Location: login.php'); exit; }
function nam_admin_detail_e(?string $value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function nam_admin_detail_money(float|int|string $value): string { return number_format((float)$value, 0, ',', '.') . ' đ'; }
if (empty($_SESSION['_nam_admin_order_csrf'])) $_SESSION['_nam_admin_order_csrf'] = bin2hex(random_bytes(32));
$model = new OrderModel($conn); $order = $model->find((int)($_GET['id'] ?? 0)); if(!$order){http_response_code(404);exit('Không tìm thấy đơn hàng.');}
$notice = $_SESSION['_nam_admin_order_flash'] ?? null; unset($_SESSION['_nam_admin_order_flash']);
$next = $model->nextStatuses($order['status']);
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= nam_admin_detail_e($order['order_code']) ?></title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="page" style="max-width:1200px;margin:auto"><div class="page-head"><div><a class="text-muted" href="order_management.php">← Quản lý đơn hàng</a><h2 style="margin-top:10px">Đơn <?= nam_admin_detail_e($order['order_code']) ?></h2><p>Đặt lúc <?= date('d/m/Y H:i',strtotime($order['created_at'])) ?></p></div><span class="badge <?= nam_admin_detail_e($order['status']) ?>"><?= nam_admin_detail_e($model->statusText($order['status'])) ?></span></div><?php if($notice):?><div class="alert alert-<?= nam_admin_detail_e($notice['type']) ?>"><?= nam_admin_detail_e($notice['message']) ?></div><?php endif;?><div class="order-layout"><div><section class="card"><h3>Sản phẩm đặt mua</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Sản phẩm</th><th>SKU</th><th>Đơn giá</th><th>SL</th><th>Thành tiền</th></tr></thead><tbody><?php foreach($order['items'] as $item):?><tr><td><strong><?= nam_admin_detail_e($item['product_name']) ?></strong><br><small class="text-muted"><?= nam_admin_detail_e($item['variant_label']) ?></small></td><td><?= nam_admin_detail_e($item['sku']) ?></td><td><?= nam_admin_detail_money($item['price']) ?></td><td><?= (int)$item['quantity'] ?></td><td><?= nam_admin_detail_money($item['price']*$item['quantity']) ?></td></tr><?php endforeach;?></tbody></table></div><p style="text-align:right"><strong>Tạm tính: <?= nam_admin_detail_money($order['subtotal']) ?></strong><br>Vận chuyển: <?= nam_admin_detail_money($order['shipping_fee']) ?><br><strong style="font-size:20px">Tổng: <?= nam_admin_detail_money($order['total']) ?></strong></p></section></div><aside><section class="card"><h3>Thông tin khách hàng</h3><div class="info-list"><div class="info-item"><small>Họ tên</small><?= nam_admin_detail_e($order['customer_name']) ?></div><div class="info-item"><small>Điện thoại</small><?= nam_admin_detail_e($order['phone']) ?></div><div class="info-item"><small>Email</small><?= nam_admin_detail_e($order['email'] ?: '—') ?></div><div class="info-item"><small>Thanh toán</small><?= $order['payment_method']==='cod'?'COD':'ZaloPay' ?> · <?= $order['payment_status']==='paid'?'Đã thanh toán':'Chưa thanh toán' ?></div><div class="info-item" style="grid-column:1/-1"><small>Địa chỉ</small><?= nl2br(nam_admin_detail_e($order['address'])) ?></div><?php if($order['note']):?><div class="info-item" style="grid-column:1/-1"><small>Ghi chú</small><?= nl2br(nam_admin_detail_e($order['note'])) ?></div><?php endif;?></div></section><?php if($next):?><section class="card" style="margin-top:18px"><h3>Cập nhật trạng thái</h3><form method="post" action="../controllers/OrderController.php"><input type="hidden" name="csrf_token" value="<?= nam_admin_detail_e($_SESSION['_nam_admin_order_csrf']) ?>"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><div class="field"><label>Chuyển sang</label><select name="status"><?php foreach($next as $status):?><option value="<?= $status ?>"><?= nam_admin_detail_e($model->statusText($status)) ?></option><?php endforeach;?></select></div><button class="btn btn-primary" style="margin-top:14px">Cập nhật đơn hàng</button></form></section><?php endif;?></aside></div></main></body></html>
